package vn.edu.hunre.nhom11.carrental.payment.service;
import java.math.BigDecimal;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import vn.edu.hunre.nhom11.carrental.booking.service.BookingService;import vn.edu.hunre.nhom11.carrental.payment.domain.Payment;import vn.edu.hunre.nhom11.carrental.payment.repository.PaymentRepository;import vn.edu.hunre.nhom11.carrental.shared.exception.ApiException;
@Service public class PaymentService{private final PaymentRepository payments;private final BookingService bookings;public PaymentService(PaymentRepository p,BookingService b){payments=p;bookings=b;}@Transactional public Payment pay(Long bookingId,BigDecimal amount,Payment.Method method){var b=bookings.get(bookingId);if(amount==null||amount.signum()<=0||b.getPaidAmount().add(amount).compareTo(b.getTotalAmount())>0)throw new ApiException(HttpStatus.BAD_REQUEST,"Số tiền thanh toán không hợp lệ");Payment p=new Payment();p.setBooking(b);p.setAmount(amount);p.setMethod(method);p.setTransactionCode("TX-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());b.setPaidAmount(b.getPaidAmount().add(amount));return payments.save(p);}public Object byBooking(Long id){return payments.findByBookingId(id);}}

